import { test, expect } from '@playwright/test';

test.describe('Account Lock After Failed Login Attempts', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should lock account after 5 failed login attempts', async ({ page }) => {
    // Setup: Mock API response for failed login attempts
    await page.route('**/api/auth/login', async (route) => {
      await route.abort('failed');
    });

    // First failed attempt
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('admin@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('wrongpassword');

    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/invalid credentials/i);
    await expect(errorMessage).toBeVisible();

    // Second failed attempt
    await passwordInput.fill('wrongpassword');
    await loginButton.click();

    await expect(errorMessage).toBeVisible();

    // Third failed attempt
    await passwordInput.fill('wrongpassword');
    await loginButton.click();

    await expect(errorMessage).toBeVisible();

    // Fourth failed attempt
    await passwordInput.fill('wrongpassword');
    await loginButton.click();

    await expect(errorMessage).toBeVisible();

    // Fifth failed attempt
    await passwordInput.fill('wrongpassword');
    await loginButton.click();

    // Verify account is locked
    const lockMessage = page.getByText(/account locked/i);
    await expect(lockMessage).toBeVisible();

    // Verify login button is disabled
    const loginButtonDisabled = page.getByRole('button', { name: /login/i });
    await expect(loginButtonDisabled).toBeDisabled();

    // Verify email is displayed
    const emailDisplay = page.getByText('admin@example.com');
    await expect(emailDisplay).toBeVisible();

    // Verify lockout message is displayed
    const lockoutMessage = page.getByText(/account locked/i);
    await expect(lockoutMessage).toBeVisible();

    // Verify lockout duration
    const lockoutDuration = page.getByText(/locked for 15 minutes/i);
    await expect(lockoutDuration).toBeVisible();

    // Verify reset button is available
    const resetButton = page.getByRole('button', { name: /reset password/i });
    await expect(resetButton).toBeVisible();

    // Verify reset link is present
    const resetLink = page.getByRole('link', { name: /reset password/i });
    await expect(resetLink).toBeVisible();

    // Verify admin dashboard is accessible
    const adminDashboard = page.getByRole('region', { name: /admin dashboard/i });
    await expect(adminDashboard).toBeVisible();
  });

  test('should unlock account after successful login after lockout', async ({ page }) => {
    // Setup: Mock API response for successful login
    await page.route('**/api/auth/login', async (route) => {
      await route.continue();
    });

    // Lock account by simulating 5 failed login attempts
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('admin@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('wrongpassword');

    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Verify account is locked
    const lockMessage = page.getByText(/account locked/i);
    await expect(lockMessage).toBeVisible();

    // Wait for lockout duration
    await page.waitForTimeout(90000);

    // Verify account is unlocked
    const unlockMessage = page.getByText(/account unlocked/i);
    await expect(unlockMessage).toBeVisible();

    // Verify lockout duration is cleared
    const lockoutDuration = page.getByText(/locked for 15 minutes/i);
    await expect(lockoutDuration).not.toBeVisible();

    // Verify account is accessible
    const adminDashboard = page.getByRole('region', { name: /admin dashboard/i });
    await expect(adminDashboard).toBeVisible();

    // Verify admin dashboard is visible
    const dashboardLink = page.getByRole('link', { name: /admin dashboard/i });
    await expect(dashboardLink).toBeVisible();

    // Verify admin dashboard is accessible
    await expect(adminDashboard).toBeVisible();

    // Verify account is accessible
    const accountLink = page.getByRole('link', { name: /account/i });
    await expect(accountLink).toBeVisible();

    // Verify account details are displayed
    const accountDetails = page.getByText(/admin@example.com/i);
    await expect(accountDetails).toBeVisible();

    // Verify account recovery options are available
    const recoveryOptions = page.getByRole('link', { name: /recover account/i });
    await expect(recoveryOptions).toBeVisible();

    // Verify account settings are available
    const accountSettings = page.getByRole('link', { name: /account settings/i });
    await expect(accountSettings).toBeVisible();

    // Verify account security settings are available
    const securitySettings = page.getByRole('link', { name: /security settings/i });
    await expect(securitySettings).toBeVisible();

    // Verify account lockout reason is displayed
    const lockoutReason = page.getByText(/locked due to failed login attempts/i);
    await expect(lockoutReason).toBeVisible();

    // Verify account is no longer locked
    const lockMessage = page.getByText(/account locked/i);
    await expect(lockMessage).not.toBeVisible();
  });
});
